// Fusionne plusieurs listes classées en un seul classement.
// TODO : ceci garde l'ordre de la 1re liste et colle les nouveaux ids à la fin.
//        Il faut au contraire SOMMER 1/(K+rang) sur toutes les listes : un doc
//        présent en bonne place dans plusieurs listes doit remonter.
export function fuse(lists, K = 60) {
  const out = [...lists[0]];
  for (const list of lists.slice(1)) {
    for (const id of list) if (!out.includes(id)) out.push(id);
  }
  return out;
}

